const now = new Date();
const y0 = now.getUTCFullYear();
const m0 = now.getUTCMonth();
const year  = m0 === 0 ? y0 - 1 : y0;
const month = m0 === 0 ? 12 : m0;
const start = new Date(Date.UTC(year, month - 1, 1));
const end   = new Date(Date.UTC(year, month, 0));
const fmt = (d) => d.toISOString().slice(0, 10);
const fmtDe = (d) => `${String(d.getUTCDate()).padStart(2,'0')}.${String(d.getUTCMonth()+1).padStart(2,'0')}.${d.getUTCFullYear()}`;
const monthNames = ['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
const monthName = monthNames[month - 1];
const month_iso = `${year}-${String(month).padStart(2,'0')}`;
const start_date = fmt(start);
const end_date = fmt(end);
const HOURLY_RATE = 23.80;
const VAT_PERCENT = 19;
const toggl_body = JSON.stringify({
  start_date, end_date,
  order_by: 'date', order_dir: 'ASC',
  page_size: 1000
});
const toggl_pdf_body = JSON.stringify({
  start_date, end_date,
  order_by: 'date', order_dir: 'ASC',
  display_mode: 'date_and_time',
  duration_format: 'classic'
});
return [{ json: {
  start_date, end_date,
  start_de: fmtDe(start),
  end_de: fmtDe(end),
  year, month, month_name: monthName, month_iso,
  filename: `Toggl-Report_${month_iso}.pdf`,
  subject: `Toggl-Monatsreport Sebastian ${monthName} ${year}`,
  hourly_rate: HOURLY_RATE,
  vat_percent: VAT_PERCENT,
  toggl_body,
  toggl_pdf_body
} }];

const meta = $('Calc Vormonat').first().json;
const list = $input.all().map(i => i.json);

const TAG_LOOKUP = {
  20353637: 'Bundles',
  20372675: 'Externer Traffic',
  20316408: 'Flatfiles',
  20281019: 'Monthly Tasks'
};

const entries = [];
let totalSeconds = 0;
for (const grp of list) {
  const tagNames = (grp.tag_ids || []).map(t => TAG_LOOKUP[t] || `tag_${t}`);
  for (const te of (grp.time_entries || [])) {
    const secs = te.seconds || 0;
    totalSeconds += secs;
    entries.push({
      date: (te.start || '').slice(0, 10),
      desc: grp.description || '(kein Titel)',
      tags: tagNames,
      duration_min: Math.round(secs / 60),
      billable: !!grp.billable
    });
  }
}

const totalH = (totalSeconds / 3600).toFixed(2);
const totalH_de = totalH.replace('.', ',');

const rate = meta.hourly_rate;
const vat  = meta.vat_percent;
const hours = parseFloat(totalH);
const net   = Math.round(hours * rate * 100) / 100;
const vatAmount = Math.round(net * vat / 100 * 100) / 100;
const gross = Math.round((net + vatAmount) * 100) / 100;
const de = (n) => n.toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const userPrompt = `${meta.month_name} ${meta.year} (${meta.start_date} bis ${meta.end_date}), Gesamt ${totalH_de} h.\nEntries:\n${JSON.stringify(entries)}`;

const systemPrompt = `Du bist Reporting-Assistent fuer einen Freelancer. Du fasst Monats-Stunden zusammen.

Eingabe: JSON-Array Time-Entries mit date, desc, tags, duration_min.

Output: Nur HTML-Snippet (kein Markdown, keine Code-Fences). Format:
<p><strong>Gesamtstunden ${meta.month_name}:</strong> {X,X} h</p>
<ul><li><strong>{Themenname}</strong> ({X,X} h) -- {Knappe Aufzaehlung}</li></ul>

Regeln:
- 4-7 Bullet Points, sortiert absteigend nach Stunden
- Gruppiere nach inhaltlichem Thema (Tags + Beschreibungs-Cluster), NICHT nach Datum
- Untagged Entries clustern (Calls & Abstimmung, Listing-Pflege, Pricing & Setup)
- Themennamen praegnant max 4 Worte, Marktplatz-Kontext erlaubt (z.B. Bundles FR/IE)
- Sachlich knapp, deutsch, neutral (kein Du/Sie)
- Keine Floskeln
- Stunden mit Komma (1,5 h), eine Stelle nach Komma
- ASIN-Codes nur wenn inhaltlich relevant
- Output: NUR HTML, nichts davor/danach`;

const geminiBody = JSON.stringify({
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{ parts: [{ text: userPrompt }] }],
  generationConfig: { temperature: 0.3, maxOutputTokens: 1000, thinkingConfig: { thinkingBudget: 0 } }
});

return [{ json: {
  ...meta,
  total_hours: hours,
  total_hours_de: totalH_de,
  net, vat_amount: vatAmount, gross,
  net_de: de(net), vat_de: de(vatAmount), gross_de: de(gross), rate_de: de(rate),
  entry_count: entries.length,
  has_entries: entries.length > 0,
  gemini_body: geminiBody,
  fallback_html: entries.length === 0 ? `<p><em>Keine Time-Entries in ${meta.month_name} ${meta.year} getrackt.</em></p>` : ''
} }];

const meta = $('Calc Vormonat').first().json;
const togglMeta = $('Build Gemini Input').first().json;
const geminiResp = $('Gemini Summary').first().json;

let summaryHtml = togglMeta.fallback_html || '';
if (!summaryHtml) {
  try {
    summaryHtml = geminiResp.candidates[0].content.parts[0].text.trim();
    summaryHtml = summaryHtml.replace(/^```html\s*/i, '').replace(/\s*```$/, '').trim();
  } catch (e) {
    summaryHtml = `<p><em>(KI-Zusammenfassung konnte nicht generiert werden: ${String((e && e.message) || e)})</em></p>`;
  }
}

const subject = `${meta.subject}: ${togglMeta.total_hours_de} h (${togglMeta.gross_de} € brutto)`;

const htmlMessage = `<p>Hey,</p>
<p>Monatsreport ${meta.month_name} ${meta.year} ist fertig — Zeit für die easybill-Rechnung.</p>
${summaryHtml}
<p><strong>Rechnungsbetrag</strong></p>
<ul>
  <li>Stunden: ${togglMeta.total_hours_de} h</li>
  <li>Stundensatz: ${togglMeta.rate_de} € / h netto</li>
  <li>Netto: ${togglMeta.net_de} €</li>
  <li>USt ${meta.vat_percent} %: ${togglMeta.vat_de} €</li>
  <li><strong>Brutto: ${togglMeta.gross_de} €</strong></li>
</ul>
<p>Detailreport als PDF im Anhang. → easybill öffnen, Rechnung tippen, Toggl-PDF mit anhängen.</p>
<p>Lieben Gruß,<br>Sebastian</p>`;

const item = $input.first();
if (item.binary && item.binary.data) {
  item.binary.data.fileName = meta.filename;
  item.binary.data.mimeType = 'application/pdf';
}
item.json = {
  ...meta,
  subject,
  htmlMessage,
  total_hours_de: togglMeta.total_hours_de,
  net_de: togglMeta.net_de,
  gross_de: togglMeta.gross_de,
  entry_count: togglMeta.entry_count
};
return [item];
